import{_ as a,o as t,c as o,ag as r}from"./chunks/framework.4yUrvjMt.js";const u=JSON.parse('{"title":"ADR-001: Hexagonal Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/decisions/ADR-001-hexagonal-architecture.md","filePath":"architecture/decisions/ADR-001-hexagonal-architecture.md"}'),i={name:"architecture/decisions/ADR-001-hexagonal-architecture.md"};function c(n,e,s,l,d,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-001-hexagonal-architecture" tabindex="-1">ADR-001: Hexagonal Architecture <a class="header-anchor" href="#adr-001-hexagonal-architecture" aria-label="Permalink to &quot;ADR-001: Hexagonal Architecture&quot;">​</a></h1><p><strong>Status:</strong> Accepted<br><strong>Date:</strong> 2024-01-01</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>AI agent frameworks tend to grow tightly coupled to specific LLM providers. Swapping providers or backends requires significant refactoring. We need an architecture that keeps the core domain logic independent of all external systems.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Pravaha uses hexagonal architecture (ports &amp; adapters). The <code>@pravaha/core</code> package defines all ports (interfaces). Adapters in separate packages implement those ports for specific external systems.</p><p><strong>Core ports defined in <code>@pravaha/core</code>:</strong></p><ul><li><code>MemoryStore</code> — memory backend port</li><li><code>TraceStore</code> — trace persistence port</li><li><code>Step</code> — unit of work port</li><li><code>Router</code> — routing decision port</li></ul><p><strong>Adapters implement ports:</strong></p><ul><li><code>@pravaha/adapter-claude</code> → <code>Step</code> (via <code>ClaudeLLMStep</code>)</li><li><code>@pravaha/adapter-openai</code> → <code>Step</code> (via <code>OpenAILLMStep</code>)</li><li><code>@pravaha/adapter-memory-inmemory</code> → <code>MemoryStore</code></li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Positive:</strong></p><ul><li>Core has zero dependencies on external providers</li><li>Providers are swappable at construction time with no code changes to pipelines</li><li>Core logic is fully testable without network access</li><li>New providers are addable without touching core</li></ul><p><strong>Negative:</strong></p><ul><li>More packages to maintain</li><li>Interface changes in core require updates across all adapters</li></ul>',15)])])}const g=a(i,[["render",c]]);export{u as __pageData,g as default};
